export type ParsedExerciseInstruction<
  TProgram extends string = typeof VOLARYN_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    holder: TAccountMetas[0];
    agreement: TAccountMetas[1];
    underlyingMint: TAccountMetas[2];
    usdcMint: TAccountMetas[3];
    reserve: TAccountMetas[4];
    holderUnderlying: TAccountMetas[5];
    holderUsdc: TAccountMetas[6];
    settlement: TAccountMetas[7];
    underlyingProgram: TAccountMetas[8];
    usdcProgram: TAccountMetas[9];
  };
  data: ExerciseInstructionData;
};

export function parseExerciseInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedExerciseInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 10,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      holder: getNextAccount(),
      agreement: getNextAccount(),
      underlyingMint: getNextAccount(),
      usdcMint: getNextAccount(),
      reserve: getNextAccount(),
      holderUnderlying: getNextAccount(),
      holderUsdc: getNextAccount(),
      settlement: getNextAccount(),
      underlyingProgram: getNextAccount(),
      usdcProgram: getNextAccount(),
    },
    data: getExerciseInstructionDataDecoder().decode(instruction.data),
  };
}
